{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Several previous studies showed that acupuncture was bene fi cial in the treatment of facial paralysis. However, its effectiveness is still controversial compared with drug therapy.",
      "reason": "The abstract describes the state of knowledge and an important uncertainty (controversy about effectiveness vs drugs), but does not clearly describe other key uncertainties in detail."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Therefore, this systematic review and meta-analysis was performed to assess the ef fi cacy of acupuncture for Bell ' s palsy.",
      "reason": "The need for the review is explained as being performed to assess efficacy."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "There were several meta-analyses about the acupuncture treatment for patients with Bell ' s palsy. Zhou et al [49] searched for relevant literature before 2009 and included 6 RCTs, including 537 Bell ' s palsy participants. However, due to the poor quality of the included studies, reliable conclusions cannot be drawn about the ef fi cacy of traditional acupuncture and other treatments. Kim et al [50] searched for relevant literature before June 2010. A total of 8 RCTs were included in their study. The Cochrane bias risk tool was used to assess the quality of these trials. Due to the low quality of the trials, no de fi nitive conclusions were reached. Li et al [51] searched for literature before 2015 and included 14 RCTs, including 1541 Bell palsy patients.",
      "reason": "Previous meta-analyses are identified and the limitations of their evidence (poor/low quality, no definitive conclusions) are discussed, but the evidence shown does not explicitly and directly state the rationale for conducting the current review in terms of an update/replication and does not clearly cite the exact prior work as the driver for the current review’s timing."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No description of a proposed mechanism of action for acupuncture is provided in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or hypothesised relationships between intervention components and outcomes are provided in the retrieved evidence."
    }
  ],
  "confidence": 74
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
